  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "title": {
    "text": "Total pending cases at each stage",
    "anchor": "start",
    "color": "#0A0509",
    "fontSize": "18",
    "font": "Roboto",
    "baseline": "top",
    "dx": 14,
    "fontWeight": 600,
    "subtitle": " ",
    "subtitleFontSize": 12,
    "subtitlePadding": 10
  },
  "width": 700,
  "height": 450,
  "padding": {"top": 45, "bottom": 70, "left": 90, "right": 0},
  "autosize": "none",
  "config": {"kibana": {"hideWarnings": true}},
  "data": [
    {
      "name": "caseData",
      "url": {
        "index": "case-index-v1",
        "body": {
          "size": 0,
          "track_total_hits": true,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "filingDateTime": {
                      "gte": {"%timefilter%": "min"},
                      "lte": {"%timefilter%": "max"}
                    }
                  }
                },
                {"exists": {"field": "substage.keyword"}}
              ],
              "must_not": ["%dashboard_context-must_not_clause%"],
              "filter": ["%dashboard_context-filter_clause%"]
            }
          },
          "aggs": {
            "substages": {
              "terms": {
                "field": "substage.keyword",
                "size": 50,
                "missing": "Unknown"
              }
            }
          }
        }
      },
      "format": {"property": "aggregations.substages.buckets"}
    },
    {
      "name": "substageOrder",
      "values": [
        {"substage": "Draft", "order": 0},
        {"substage": "Filing", "order": 1},
        {"substage": "Scrutiny", "order": 2},
        {"substage": "Registration", "order": 3},
        {"substage": "Cognizance", "order": 4},
        {"substage": "Inquiry", "order": 5},
        {"substage": "Appearance", "order": 6},
        {"substage": "Framing of charges", "order": 7},
        {"substage": "Evidence", "order": 8},
        {"substage": "Arguments", "order": 9},
        {"substage": "Judgement", "order": 10},
        {"substage": "Post-Judgement", "order": 11},
        {"substage": "Referred to ADR", "order": 12},
        {"substage": "Unknown", "order": 13}
      ]
    },
    {
      "name": "processedData",
      "source": "caseData",
      "transform": [
        {
          "type": "formula",
          "as": "substage",
          "expr": "datum.key == 'REFER_TO_ADR' || datum.key =='Referred to ADR' ? 'Referred to ADR' :datum.key ==  'Post-Judgement' || datum.key == 'POST_JUDGEMENT' ? 'Post-Judgement' : join([upper(datum.key)[0], substring(lower(datum.key), 1, length(datum.key))], '')"
        },
        {
          "type": "aggregate",
          "groupby": ["substage"],
          "fields": ["doc_count"],
          "ops": ["sum"],
          "as": ["count"]
        },
        {
          "type": "lookup",
          "from": "substageOrder",
          "key": "substage",
          "fields": ["substage"],
          "values": ["order"],
          "as": ["sortOrder"],
          "default": 100
        },
        {"type": "collect", "sort": {"field": "sortOrder"}}
      ]
    },
    {
      "name": "oldWeekAppearanceData",
      "url": {
        "index": "case-index-v1",
        "body": {
          "size": 0,
          "track_total_hits": true,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "filingDateTime": {"gte": "now-60d/d", "lte": "now-31d/d"}
                  }
                }
              ],
              "should": [
                {"match_phrase": {"substage.keyword": "APPEARANCE"}},
                {"match_phrase": {"substage.keyword": "Appearance"}}
              ],
              "minimum_should_match": "1",
              "must_not": ["%dashboard_context-must_not_clause%"],
              "filter": ["%dashboard_context-filter_clause%"]
            }
          }
        }
      },
      "format": {"property": "hits.total"}
    },
    {
      "name": "newWeekAppearanceData",
      "url": {
        "index": "case-index-v1",
        "body": {
          "size": 0,
          "track_total_hits": true,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "filingDateTime": {"gte": "now-30d/d", "lte": "now/d"}
                  }
                }
              ],
              "should": [
                {"match_phrase": {"substage.keyword": "APPEARANCE"}},
                {"match_phrase": {"substage.keyword": "Appearance"}}
              ],
              "minimum_should_match": "1",
              "must_not": ["%dashboard_context-must_not_clause%"],
              "filter": ["%dashboard_context-filter_clause%"]
            }
          }
        }
      },
      "format": {"property": "hits.total"}
    }
  ],
  "signals": [
    {
      "name": "hasValidData",
      "value": false,
      "update": "data('caseData').length > 0"
    },
    {"name": "totalCount", "value": 0, "update": "44"},
    {"name": "cornerRadius", "value": 5},
    {"name": "xPadding", "value": 10},
    {
      "name": "oldAppearanceCount",
      "value": 0,
      "update": "data('oldWeekAppearanceData') ? data('oldWeekAppearanceData')[0].data : 0"
    },
    {
      "name": "newAppearanceCount",
      "value": 0,
      "update": "data('newWeekAppearanceData')  ? data('newWeekAppearanceData')[0].data : 0"
    },
    {
      "name": "percentageChange",
      "value": 0,
      "update": "oldAppearanceCount !=0 ? (( newAppearanceCount - oldAppearanceCount)/oldAppearanceCount )*100: newAppearanceCount *100 "
    },
    {
      "name": "increase",
      "value": true,
      "update": "percentageChange >=0 ? true : false"
    },
    {
      "name": "countWidth",
      "value": 2,
      "update": "isNumber(newAppearanceCount) ? length(replace(newAppearanceCount, /[^0-9]/g, ''))*10 : 9"
    },
    {
      "name": "percetageWidth",
      "value": 2,
      "update": "isNumber(percentageChange) ? length(replace(format(percentageChange,'.2f'), /[^0-9]/g, ''))*9 : 9"
    }
  ],
  "scales": [
    {
      "name": "xscale",
      "type": "linear",
      "range": [{"signal": "xPadding"}, {"signal": "width - xPadding"}],
      "domain": {"data": "processedData", "field": "count", "nice": true}
    },
    {
      "name": "yscale",
      "type": "band",
      "range": "height",
      "padding": 0.1,
      "domain": {"data": "processedData", "field": "substage"}
    }
  ],
  "axes": [
    {"orient": "bottom", "scale": "xscale"},
    {"orient": "left", "scale": "yscale"}
  ],
  "marks": [
    {
      "type": "rect",
      "from": {"data": "processedData"},
      "encode": {
        "enter": {
          "x": {"scale": "xscale", "field": "count"},
          "x2": {"scale": "xscale", "value": 0},
          "y": {"scale": "yscale", "field": "substage"},
          "height": {"scale": "yscale", "band": 0.5},
          "fill": {"value": "#86BABD"},
          "cornerRadiusTopRight": {"signal": "cornerRadius"},
          "cornerRadiusBottomRight": {"signal": "cornerRadius"},
          "tooltip": {"signal": "datum.substage + ': ' + datum.count"}
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "enter": {
          "align": {"value": "center"},
          "baseline": {"value": "middle"},
          "x": {"signal": "width / 2"},
          "y": {"signal": "height / 2"},
          "text": {"value": "No data"},
          "fontSize": {"value": 14},
          "fill": {"value": "gray"}
        },
        "update": {"opacity": {"signal": "hasValidData ? 0 : 1"}}
      }
    },
    {
      "type": "group",
      "marks": [
        {
          "type": "text",
          "encode": {
            "enter": {
              "align": {"value": "left"},
